-- SRD 3.5 Equipment: Open Game Content under OGL 1.0a.
-- Source: https://github.com/olimot/srd-v3.5-md/blob/main/basic-rules-and-legal/equipment.md
-- Prices are normalized to gp; original currency and category data remain in detalhes.
on conflict(id) do update set nome=case when srd_equipment.srd_source_url is null then srd_equipment.nome else excluded.nome end,tipo=excluded.tipo,dano=excluded.dano,critico=excluded.critico,tipo_dano=excluded.tipo_dano,ca_bonus=excluded.ca_bonus,max_des=excluded.max_des,penalidade_armadura=excluded.penalidade_armadura,peso=excluded.peso,preco=excluded.preco,descricao=excluded.descricao,srd_source_url=excluded.srd_source_url,categoria=excluded.categoria,bonus_ca=excluded.bonus_ca,bonus_max_des=excluded.bonus_max_des,custo_po=excluded.custo_po,detalhes=excluded.detalhes;
